/// <summary>
/// MPJ_22902_CustomerNumbering
/// </summary>
public class METCreateCustNumSeqDialog extends RunBase
{
    protected   Dialog         dialog;
    protected   DialogField     dlgCreateCustomer, dlgBusinessUnit, dlgState;
    private     METBusinessName metBusinessName;
    private     Integer         metState;
    
}

Method.Source:
   /// <summary>
   /// calling the updateCustomerNumSeqRec method
   /// </summary>
   /// <param name = "_args">_args</param>
   /// <returns>Customer account number</returns>
    public static CustAccount main(Args _args)
    {
        METCreateCustNumSeqDialog           dialogCreateCustNumSeqDialog;
        FormRun                             formRun = _args.caller();
        CustTable                           custTable = _args.record();

        dialogCreateCustNumSeqDialog = new METCreateCustNumSeqDialog();

        if (dialogCreateCustNumSeqDialog.prompt())
        {
            dialogCreateCustNumSeqDialog.updateCustomerNumSeqRec(custTable);
        }
        else
        {
            formRun.close();
        }

        return custTable.AccountNum;
    }

    /// <summary>
    /// update the customer number sequence
    /// </summary>
    /// <param name = "_custTable">_custTable</param>
    private void updateCustomerNumSeqRec(CustTable _custTable)
    {
        str                     numberSequence;
        RefRecId                numberseqcust = CustParameters::numRefCustAccount().NumberSequenceId; 
        NumberSequenceTable     numberseqTable = NumberSequenceTable::find(numberseqcust);
        NumberSequenceReference numberSequenceReference;
        
        select firstonly numberSequenceReference
            where numberSequenceReference.NumberSequenceId == numberseqTable.RecId;

        numberSequence = NumberSeq::newGetNum(numberSequenceReference).num();
        
        if (curExt() == "@MET:METFood" || curExt() == "@MET:METLIQ")
        {
            ttsbegin;
            select firstonly forupdate numberseqTable
                where numberseqTable.Recid == numberseqcust;

            numberseqTable.Format = strReplace(numberseqTable.Format, subStr(numberseqTable.Format, 1,2), (substr(metBusinessName, 1, 1) + int2Str(metState)));
            numberseqTable.update();
            ttscommit;
        }

        switch (Curext())
        {
            case "@MET:METFood":
                numberSequence =  numberSequence;
                break;
            case "@MET:METLIQ":
                numberSequence =  numberSequence;
                break;
            case "@MET:METHWE":
                numberSequence = numberSequence;
        }

        _custTable.selectForUpdate(true);
        _custTable.AccountNum =  numberSequence;
       
    }

    /// <summary>
    /// Dialog method to capture runtime user inputs for customer details
    /// </summary>
    /// <returns>dialog</returns>
    public Object dialog()
    {
        dialog = super();
        dialog.caption("@SYS59934");

        dlgCreateCustomer        = dialog.addField(extendedTypeStr(CustAccount), "@SYS124832");
        dlgCreateCustomer.enabled(false);

        dlgBusinessUnit = dialog.addField(extendedTypeStr(METBusinessName), "@SYS313109");
        dlgBusinessUnit.registerOverrideMethod(methodStr(FormStringControl, lookup),methodStr(METCreateCustNumSeqDialog, businessUnitLookup), this);

            
        dlgState = dialog.addField(extendedTypeStr(Integer), "@SYS181123");
        dlgState.registerOverrideMethod(methodStr(FormIntControl, lookup),methodStr(METCreateCustNumSeqDialog, stateLookup), this);

        FormBuildStringControl      businessUnit;
        FormBuildIntControl         state;
        businessUnit = dlgBusinessUnit.control();
        state = dlgState.control();

        if (curExt() == "@MET:METFood" || curExt() == "@MET:METLIQ")
        {
            businessUnit.mandatory(true);
            state.mandatory(true);
        }

        if (curExt() == "@MET:METHWE")
        {
            businessUnit.enabled(false);
            state.enabled(false);
        }

        return dialog;
    }

    /// <summary>
    /// Validate the controls
    /// </summary>
    /// <param name = "_calledFrom">_calledFrom</param>
    /// <returns>boolean value</returns>
    public boolean validate(Object _calledFrom = null)
    {
        if (curExt() == "@MET:METFood" || curExt() == "@MET:METLIQ")
        {
            if (dlgBusinessUnit.value(METConstants::emptyString))
            {
                return checkFailed("@MET:METBusinessUnitValidate");
            }
            else if (dlgState.value(METConstants::emptyString))
            {
                return checkFailed("@MET:METStateValidate");
            }
        }

        return true;
    }

/// <summary>
/// Retrieves values from the dialog after it is completed.
/// </summary>
/// <returns>true if values are retrieved successfully; otherwise, false.</returns>
public boolean getFromDialog()
{
    boolean ret = true;
    if (dlgBusinessUnit)
    {
        metBusinessName = dlgBusinessUnit.value();
        metState        = dlgState.value();
    }
    
    return ret;
}

    /// <summary>
    /// Lookup for Business unit from METBusinessUnit table
    /// </summary>
    /// <param name = "_formControl">formcontrol</param>
    public void businessUnitLookup(FormStringControl _formControl)
    {
        SysTableLookup tableLookup = SysTableLookup::newParameters(tableNum(METBusinessUnit), _formControl);
        Query query;
        QueryBuildDataSource businessUnitQBDS;

        query = new Query();
        businessUnitQBDS= query.addDataSource(tableNum(METBusinessUnit));

        tableLookup.addLookupfield(fieldNum(METBusinessUnit, BusinessName));
        tableLookup.addLookupfield(fieldNum(METBusinessUnit, BusinessPrefix));

        tableLookup.parmQuery(query);
        tableLookup.performFormLookup();
    }

    /// <summary>
    /// Lookup for State  from METBusinessUnit table
    /// </summary>
    /// <param name = "_formControl">formcontrol</param>
    public void stateLookup(FormIntControl _formControl)
    {
        SysTableLookup tableLookup = SysTableLookup::newParameters(tableNum(METBusinessUnit), _formControl);
        Query query;
        QueryBuildDataSource stateQBDS;

        query = new Query();
        stateQBDS= query.addDataSource(tableNum(METBusinessUnit));

        tableLookup.addLookupfield(fieldNum(METBusinessUnit, StatePrefix));

        tableLookup.parmQuery(query);
        tableLookup.performFormLookup();
    }

/// <summary>
/// Run in the new session
/// </summary>
/// <returns>false</returns>
protected boolean canRunInNewSession()
{
    return false;
}

/// <summary>
/// Construct the METCreateCustNumSeqDialog
/// </summary>
/// <returns>METCreateCustNumSeqDialog</returns>
public static METCreateCustNumSeqDialog construct()
{
    return new METCreateCustNumSeqDialog();
}
